# US county wastewater activity and COVID-19 test positivity
# Version 1.0 | 23 October 2026
# Run: source("us_wastewater_positivity_map.R")
# Install once in a clean R session:
# install.packages(c("curl", "jsonlite", "gifski"), repos="https://cloud.r-project.org")
# No httr2, sf, R Markdown, Pandoc, external map service or source map script needed.
# GIF: gifski, magick, or a verified ImageMagick executable (Windows convert.exe
# is never used). HTML remains available if GIF encoding is unavailable.
#
# SOURCE FINDING: CDC atcp-73re publishes SITE WVALs, not complete county values.
# PMC19 summarizes sites, carries some observations forward and estimates missing
# counties. This script instead maps the median of available sites associated
# with each county in THAT WEEK. Missing counties remain missing. Multi-county
# sites contribute once to each named county and are flagged as shared proxies.
# There are no infection/prevalence estimates and no conversions to case counts.
#
# atcp-73re: Saturday-ending CDC/MMWR weeks, currently starting 2022-01-01.
# jgk8-6dpn: Wednesday-ending NAAT positivity, observed through 2023-05-10.
# A displayed Saturday is paired with the Wednesday THREE DAYS EARLIER; each
# measure retains its real seven-day dates. This is display alignment, NOT a
# same-window merge for correlation. No averaging or interpolation of percentages.
# Historical WVALs are retrospectively revised/recalibrated by CDC. Each run
# preserves source hashes, metadata, date_updated and previous snapshots on refresh.
# Category cutoffs are pinned across the entire animation, avoiding date-based
# color jumps. Current (Aug 2026) and earlier PMC-default thresholds are available.

RUN_ANALYSIS <- getOption("usww.autorun", TRUE)
OUTPUT_ROOT <- file.path("analysis", "county_wastewater_map")
REFRESH_DOWNLOADS <- FALSE # Set TRUE to obtain a new snapshot; previous runs survive
LOCAL_WASTEWATER_CSV <- "" # Optional original atcp-73re CSV, all pathogens accepted
LOCAL_POSITIVITY_CSV <- "" # Optional jgk8-6dpn CSV or national_county_weekly.csv from your map
COUNTY_CROSSWALK_CSV <- "" # Optional reviewed overrides: state_territory, county_label, fips, note
CLINICAL_SITES_CSV <- "clinical_trial_sites.csv" # Optional markers; no geographic restriction
START_DATE <- "" # Empty: full union of observed histories; otherwise first Saturday frame
END_DATE <- ""   # Empty: latest observed source period; otherwise last Saturday frame
WRITE_GIF <- TRUE
GIF_WIDTH <- 1700L
GIF_HEIGHT <- 1150L
SECONDS_PER_WEEK <- 0.35
KEEP_FRAMES <- FALSE
CATEGORY_SCHEME <- "cdc_2026" # cdc_2026 or earlier_pmc; GIF uses this choice
OPEN_HTML <- interactive()
PAGE_SIZE <- 50000L
WVAL_DATASET <- "atcp-73re"
POSITIVITY_DATASET <- "jgk8-6dpn"
WVAL_METHODS_URL <- "https://www.cdc.gov/wastewater/about/wval.html"
PMC_METHODS_URL <- "https://pmc19.com/PMC_COVID_Appendix_June292026.pdf"

wm_fail <- function(...) stop(..., call.=FALSE)
wm_now <- function() format(Sys.time(),"%Y-%m-%dT%H:%M:%SZ",tz="UTC")
wm_clean <- function(x) { x<-trimws(as.character(x));x[is.na(x)]<-"";x }
wm_csv <- function(x,p) write.csv(x,p,row.names=FALSE,na="",fileEncoding="UTF-8")
wm_read <- function(p) read.csv(p,colClasses="character",check.names=FALSE,stringsAsFactors=FALSE,na.strings="",fileEncoding="UTF-8-BOM")
wm_need <- function(x,n) if(!all(n%in%names(x)))wm_fail("Source schema changed; missing: ",paste(setdiff(n,names(x)),collapse=", "))
wm_num <- function(x) {
  s<-wm_clean(x);v<-suppressWarnings(as.numeric(s))
  if(any(s!="" & !is.finite(v)))wm_fail("Unrecognised numeric value: ",paste(head(unique(s[s!="" & !is.finite(v)]),5),collapse=", "))
  v[s==""]<-NA_real_;v
}
wm_date <- function(x) {
  d<-as.Date(substr(as.character(x),1,10),format="%Y-%m-%d")
  if(anyNA(d))wm_fail("Missing or invalid source dates.");d
}
wm_md5 <- function(p) unname(tools::md5sum(p))
wm_query <- function(base,p) paste0(base,"?",paste(vapply(seq_along(p),function(i)
  paste0(utils::URLencode(names(p)[i],reserved=TRUE),"=",utils::URLencode(as.character(p[[i]]),reserved=TRUE)),""),collapse="&"))
wm_json <- function(x) jsonlite::toJSON(x,auto_unbox=TRUE,na="null",null="null",digits=8,dataframe="rows")
wm_pack <- function(x) gsub("[\r\n]","",jsonlite::base64_enc(memCompress(charToRaw(enc2utf8(x)),type="gzip"))) # R produces zlib/deflate bytes
wm_download <- function(url,dest) {
  part<-tempfile("download_",tmpdir=dirname(dest));on.exit(unlink(part),add=TRUE)
  for(attempt in 1:3) {
    h<-curl::new_handle(timeout=300,connecttimeout=25,followlocation=TRUE,useragent="US-wastewater-map/1.0")
    a<-tryCatch(curl::curl_fetch_disk(url,part,h),error=identity)
    code<-if(inherits(a,"error"))NA_integer_ else a$status_code
    if(!is.na(code)&&code>=200&&code<300&&file.info(part)$size>0) {
      first<-readLines(part,n=1,warn=FALSE)
      if(any(grepl("^\\s*<(!doctype|html)",first,ignore.case=TRUE)))wm_fail("HTML returned instead of data: ",url)
      if(!file.copy(part,dest,overwrite=TRUE))wm_fail("Cannot save ",dest)
      return(invisible(dest))
    }
    why<-if(inherits(a,"error"))conditionMessage(a)else paste("HTTP",code)
    if(attempt==3||(!is.na(code)&&!code%in%c(408,429)&&code<500))wm_fail("Download failed: ",why,"\n",url,
      "\nNo substitute data used. A source CSV can be supplied in the settings.")
    message(why,"; retrying.");Sys.sleep(2^attempt)
  }
}

# Stage and validate the complete source before committing a reusable cache.
# Count and update timestamp are checked before AND after pagination.
wm_source <- function(dataset,where,fields,order,cache,run,local="") {
  folder<-file.path(cache,dataset);manifest<-file.path(folder,"manifest.rds")
  signature<-list(dataset=dataset,where=where,fields=fields,order=order)
  if(nzchar(local)) {
    if(!file.exists(local))wm_fail("Local input not found: ",local)
    x<-wm_read(local)
    return(list(data=x,manifest=list(dataset=dataset,mode="local",path=normalizePath(local,winslash="/"),
      acquired_utc=NA_character_,md5=wm_md5(local),rows=nrow(x)),folder=NULL))
  }
  if(!REFRESH_DOWNLOADS&&file.exists(manifest)) {
    m<-readRDS(manifest)
    if(!identical(m$signature,signature))wm_fail("Cache query mismatch: ",folder)
    paths<-file.path(folder,m$files)
    if(any(!file.exists(paths))||!identical(unname(tools::md5sum(paths)),m$hashes))wm_fail("Cache integrity failure. Set REFRESH_DOWNLOADS <- TRUE.")
    x<-do.call(rbind,lapply(paths[grepl("^page_",basename(paths))],wm_read))
    if(nrow(x)!=m$rows)wm_fail("Cached extraction is incomplete.")
    return(list(data=x,manifest=m,folder=folder))
  }
  staging<-tempfile(paste0(dataset,"_pending_"),tmpdir=cache);dir.create(staging)
  on.exit(unlink(staging,recursive=TRUE),add=TRUE)
  base<-paste0("https://data.cdc.gov/resource/",dataset,".csv")
  select_count<-if(dataset==WVAL_DATASET)"count(*) as n,min(date_updated) as first_update,max(date_updated) as last_update" else "count(*) as n"
  count_url<-wm_query(base,list(`$select`=select_count,`$where`=where))
  first_count<-file.path(staging,"count_before.csv");wm_download(count_url,first_count)
  inventory<-wm_read(first_count);wm_need(inventory,"n");n<-wm_num(inventory$n)
  if(length(n)!=1L||is.na(n)||n<1L||n>5000000)wm_fail("Unexpected CDC row count.")
  wm_download(paste0("https://data.cdc.gov/api/views/",dataset,".json"),file.path(staging,"metadata.json"))
  meta_before<-jsonlite::fromJSON(file.path(staging,"metadata.json"))
  pieces<-list();urls<-count_url
  for(i in seq_len(ceiling(n/PAGE_SIZE))) {
    message("CDC ",dataset,": page ",i," / ",ceiling(n/PAGE_SIZE))
    u<-wm_query(base,list(`$select`=fields,`$where`=where,`$order`=order,`$limit`=PAGE_SIZE,`$offset`=(i-1L)*PAGE_SIZE))
    p<-file.path(staging,sprintf("page_%03d.csv",i));wm_download(u,p);z<-wm_read(p)
    wm_need(z,strsplit(fields,",",fixed=TRUE)[[1]])
    if(nrow(z)!=min(PAGE_SIZE,n-(i-1L)*PAGE_SIZE))wm_fail("CDC pagination changed/incomplete; rerun.")
    pieces[[i]]<-z;urls<-c(urls,u)
  }
  wm_download(count_url,file.path(staging,"count_after.csv"))
  wm_download(paste0("https://data.cdc.gov/api/views/",dataset,".json"),file.path(staging,"metadata_after.json"))
  meta_after<-jsonlite::fromJSON(file.path(staging,"metadata_after.json"))
  if(!identical(inventory,wm_read(file.path(staging,"count_after.csv")))||
     !identical(meta_before$rowsUpdatedAt,meta_after$rowsUpdatedAt))wm_fail("CDC updated during download. Rerun for a consistent snapshot.")
  x<-do.call(rbind,pieces)
  files<-list.files(staging);hashes<-unname(tools::md5sum(file.path(staging,files)))
  m<-list(signature=signature,dataset=dataset,mode="CDC API",acquired_utc=wm_now(),rows=n,
    source_rows_updated=meta_after$rowsUpdatedAt,inventory=inventory,urls=urls,files=files,hashes=hashes)
  # Save previous source bytes inside the new run before replacing a refreshed cache.
  if(dir.exists(folder)) {
    old<-file.path(run,"previous_source_snapshot");dir.create(old,showWarnings=FALSE)
    if(!file.copy(folder,old,recursive=TRUE))wm_fail("Cannot preserve previous snapshot.")
    unlink(folder,recursive=TRUE)
  }
  saveRDS(m,file.path(staging,"manifest.rds"))
  if(!file.rename(staging,folder))wm_fail("Cannot commit source cache.")
  list(data=x,manifest=m,folder=folder)
}

wm_normalize <- function(x) {
  x<-tolower(iconv(wm_clean(x),from="UTF-8",to="ASCII//TRANSLIT"))
  x<-gsub("\\bst[.]?\\b","saint",x,perl=TRUE)
  x<-sub(" (city and borough|census area|municipality|county|parish|borough)$","",x)
  gsub("[^a-z0-9]","",x)
}
wm_areas <- function(counties) {
  p<-lapply(counties$features,`[[`,"properties")
  d<-data.frame(fips=vapply(p,`[[`,"","fips"),state=vapply(p,`[[`,"","state"),
    name=vapply(p,`[[`,"","name"),state_name=vapply(p,`[[`,"","state_name"))
  if(anyDuplicated(d$fips))wm_fail("Duplicate boundary FIPS.")
  d[order(d$fips),]
}
wm_county_links <- function(raw,areas,run) {
  descriptors<-unique(raw[c("state_territory","counties_served")]);descriptors$descriptor_id<-seq_len(nrow(descriptors))
  labels<-strsplit(gsub(";",",",wm_clean(descriptors$counties_served)),",",fixed=TRUE)
  labels<-lapply(labels,function(x)if(length(x))trimws(x)else "")
  links<-data.frame(descriptor_id=rep(descriptors$descriptor_id,lengths(labels)),county_label=unlist(labels),stringsAsFactors=FALSE)
  links$state_territory<-descriptors$state_territory[links$descriptor_id]
  states<-unique(areas[c("state","state_name")])
  sk<-wm_normalize(states$state_name);state<-states$state[match(wm_normalize(links$state_territory),sk)]
  state[wm_normalize(links$state_territory)==wm_normalize("U.S. Virgin Islands")]<-"VI"
  state[links$state_territory%in%states$state]<-links$state_territory[links$state_territory%in%states$state]
  keys<-paste(areas$state,wm_normalize(areas$name));query<-paste(state,wm_normalize(links$county_label))
  if(anyDuplicated(keys))wm_fail("Ambiguous normalized boundary names.")
  hit<-match(query,keys);links$mapping_note<-"state + normalized county name"
  # Some independent cities are reported without the City suffix. Only exact,
  # unique City-suffix matches are added; no fuzzy or neighboring-county matching.
  fallback<-is.na(hit)&nzchar(links$county_label)
  hit[fallback]<-match(paste0(query[fallback],"city"),keys)
  links$mapping_note[fallback & !is.na(hit)]<-"unique independent-city suffix match"
  links$fips<-areas$fips[hit]
  # Census 2020 spells these islands St. Thomas Island, etc. Explicit same-island aliases.
  vi<-state=="VI" & wm_normalize(links$county_label)=="saintthomas"
  vi[is.na(vi)]<-FALSE;links$fips[vi]<-"78030";links$mapping_note[vi]<-"Saint Thomas = St. Thomas Island (Census 78030)"
  if(nzchar(COUNTY_CROSSWALK_CSV)) {
    override<-wm_read(COUNTY_CROSSWALK_CSV);wm_need(override,c("state_territory","county_label","fips","note"))
    key<-paste(override$state_territory,override$county_label)
    if(anyDuplicated(key)||any(!override$fips%in%areas$fips)||any(!nzchar(wm_clean(override$note))))wm_fail("Invalid reviewed county crosswalk.")
    h<-match(paste(links$state_territory,links$county_label),key);ok<-!is.na(h)
    links$fips[ok]<-override$fips[h[ok]];links$mapping_note[ok]<-paste("reviewed override:",override$note[h[ok]])
  }
  links$mapping_note[is.na(links$fips)]<-"unresolved; not mapped (no cross-state guessing)"
  wm_csv(links,file.path(run,"data","county_name_crosswalk.csv"))
  wm_csv(unique(links[is.na(links$fips),c("state_territory","county_label","mapping_note")]),file.path(run,"data","unresolved_county_names.csv"))
  raw$descriptor_id<-match(paste(raw$state_territory,raw$counties_served),paste(descriptors$state_territory,descriptors$counties_served))
  original_counts<-lengths(labels)
  known<-unique(links[!is.na(links$fips),c("descriptor_id","fips")])
  list(raw=raw,links=known,unresolved=sum(is.na(links$fips)),
    shared_descriptor=descriptors$descriptor_id[original_counts>1L])
}
wm_prepare_wastewater <- function(raw,areas,run) {
  required<-c("state_territory","counties_served","site","population_served","source","site_wval",
    "site_wval_category","week_end","pathogen_target","date_updated")
  wm_need(raw,required);raw<-raw[wm_clean(raw$pathogen_target)=="SARS-CoV-2",required]
  if(!nrow(raw))wm_fail("No SARS-CoV-2 WVAL rows.")
  raw$week_end<-wm_date(raw$week_end);raw$site_wval<-wm_num(raw$site_wval)
  if(any(as.POSIXlt(raw$week_end)$wday!=6L)||any(raw$site_wval<0,na.rm=TRUE)||any(!nzchar(wm_clean(raw$site))))wm_fail("Invalid wastewater date/value/site identifier.")
  key<-paste(raw$site,raw$week_end)
  if(anyDuplicated(key)) {
    dup<-duplicated(key)|duplicated(key,fromLast=TRUE);wm_csv(raw[dup,],file.path(run,"data","duplicate_site_weeks.csv"))
    raw<-unique(raw)
    if(anyDuplicated(paste(raw$site,raw$week_end)))wm_fail("Conflicting site-week records; see duplicate_site_weeks.csv. No source is selected silently.")
  }
  wm_csv(raw,file.path(run,"data","wastewater_site_weekly.csv"))
  wm_csv(raw[is.finite(raw$site_wval)&raw$site_wval>60,],file.path(run,"data","large_wval_review.csv"))
  # Flag unusually large published values for review; retain them, never cap or
  # convert WVAL to an infection percentage. 60 is an operational review marker.
  mapping<-wm_county_links(raw,areas,run)
  long<-merge(mapping$raw,mapping$links,by="descriptor_id")
  long<-long[is.finite(long$site_wval),]
  long$shared<-long$descriptor_id%in%mapping$shared_descriptor
  if(anyDuplicated(long[c("site","week_end","fips")]))wm_fail("Duplicate site/county/week linkage.")
  message("Summarizing reporting sites by county and week...")
  groups<-split(seq_len(nrow(long)),paste(long$fips,long$week_end));first<-vapply(groups,`[`,integer(1),1L)
  county<-data.frame(fips=long$fips[first],week_end=long$week_end[first],
    wval=vapply(groups,function(i)median(long$site_wval[i]),numeric(1)),
    sites=lengths(groups),shared_sites=vapply(groups,function(i)sum(long$shared[i]),integer(1)),
    minimum_site_wval=vapply(groups,function(i)min(long$site_wval[i]),numeric(1)),
    maximum_site_wval=vapply(groups,function(i)max(long$site_wval[i]),numeric(1)),
    site_ids=vapply(groups,function(i)paste(sort(long$site[i]),collapse=";"),""),row.names=NULL)
  county<-county[order(county$week_end,county$fips),];county$week_start<-county$week_end-6L
  wm_csv(county,file.path(run,"data","wastewater_county_weekly.csv"))
  # Site membership changes can create apparent jumps in county medians.
  county<-county[order(county$fips,county$week_end),]
  prior<-match(paste(county$fips,county$week_end-7L),paste(county$fips,county$week_end))
  county$site_membership_changed<-!is.na(prior)&county$site_ids!=county$site_ids[prior]
  wm_csv(county[county$site_membership_changed,],file.path(run,"data","site_membership_changes.csv"))
  list(county=county,raw=raw,unresolved=mapping$unresolved,large_values=sum(raw$site_wval>60,na.rm=TRUE))
}
wm_prepare_positivity <- function(x,areas,run) {
  if(all(c("fips_code","date","percent_test_results_reported")%in%names(x))) {
    z<-data.frame(fips=x$fips_code,week_end=wm_date(x$date),positivity=wm_num(x$percent_test_results_reported))
  } else {
    wm_need(x,c("geography_level","geography_id","week_start","week_end","positivity_pct"))
    x<-x[wm_clean(x$geography_level)=="county",]
    if("positivity_status"%in%names(x)) {
      bad<-is.finite(wm_num(x$positivity_pct))&!tolower(wm_clean(x$positivity_status))%in%c("reported","observed","available")
      if(any(bad))wm_fail("Local positivity contains substituted/estimated values. Supply the original CDC archive.")
    }
    z<-data.frame(fips=x$geography_id,week_end=wm_date(x$week_end),positivity=wm_num(x$positivity_pct))
    if(any(wm_date(x$week_start)!=z$week_end-6L))wm_fail("Local positivity must use seven-day periods.")
  }
  z$fips<-sprintf("%05d",as.integer(z$fips))
  if(any(as.POSIXlt(z$week_end)$wday!=3L)||anyDuplicated(z[c("fips","week_end")])||
    any(z$positivity<0|z$positivity>100,na.rm=TRUE))wm_fail("Invalid positivity: requires unique county/Wednesday weeks and percentages 0..100.")
  absent<-!z$fips%in%areas$fips
  wm_csv(z[absent,],file.path(run,"data","unmapped_positivity.csv"))
  if(any(absent&is.finite(z$positivity)))wm_fail("Positivity contains observed values for unmatched boundary FIPS; inspect unmapped_positivity.csv.")
  z<-z[!absent,];z$week_start<-z$week_end-6L
  wm_csv(z,file.path(run,"data","positivity_county_weekly.csv"));z
}
wm_class <- function(v,scheme=CATEGORY_SCHEME) {
  cuts<-if(scheme=="cdc_2026")c(2.6,4.9,7.9,11.6)else c(2,3.4,5.3,7.8)
  k<-rep(NA_integer_,length(v));ok<-is.finite(v);k[ok]<-1L+rowSums(outer(v[ok],cuts,`>`));k
}
wm_colours <- function() c("#d9eaf5","#8ec7df","#f6d76a","#e8893c","#a92736")
wm_labels <- function(scheme=CATEGORY_SCHEME) if(scheme=="cdc_2026")c("Very low: <=2.6","Low: >2.6-4.9","Moderate: >4.9-7.9","High: >7.9-11.6","Very high: >11.6")else
  c("Very low: <=2.0","Low: >2.0-3.4","Moderate: >3.4-5.3","High: >5.3-7.8","Very high: >7.8")
wm_encoder <- function() {
  if(requireNamespace("gifski",quietly=TRUE))return(list(type="gifski"))
  if(requireNamespace("magick",quietly=TRUE))return(list(type="magick"))
  candidates<-c(Sys.which("magick"),if(.Platform$OS.type!="windows")Sys.which("convert"))
  for(p in candidates[nzchar(candidates)]) {
    v<-tryCatch(system2(p,"-version",stdout=TRUE,stderr=TRUE),error=function(e)character())
    if(any(grepl("ImageMagick",v,fixed=TRUE)))return(list(type="imagemagick",exe=unname(p)))
  }
  wm_fail("HTML and CSV files are ready, but no GIF encoder is available. In a clean R session install.packages('gifski'), then rerun; cached data will be reused.")
}

wm_frame <- function(path,k,weeks,county,cs,ss,areas,sites) {
  grDevices::png(path,width=GIF_WIDTH,height=GIF_HEIGHT,res=125,pointsize=13,bg="white",
    type=if(capabilities("cairo"))"cairo"else getOption("bitmapType","Xlib"))
  on.exit(grDevices::dev.off(),add=TRUE)
  par(mar=c(0,0,0,0),xaxs="i",yaxs="i",family="sans");plot.new();plot.window(xlim=c(0,1),ylim=c(0,1))
  z<-county[county$week_end==weeks[k],];cfi<-vapply(cs,function(x)x$properties$fips,"");st<-vapply(cs,function(x)x$properties$state,"")
  sst<-vapply(ss,function(x)x$properties$state,"");v<-z$wval[match(cfi,z$fips)];bins<-wm_class(v);bins[is.na(bins)]<-0L
  text(.03,.975,"United States | COVID-19 wastewater activity",adj=c(0,1),font=2,cex=1.45,col="#153b50")
  text(.03,.935,paste(format(weeks[k]-6,"%d %b %Y"),"-",format(weeks[k],"%d %b %Y")),adj=c(0,1),font=2,cex=1.1)
  text(.97,.935,paste(nrow(z),"of",nrow(areas),"county areas with linked site data"),adj=c(1,1),cex=.85,col="#536978")
  regions<-wm_regions();extra<-vapply(regions[-1],`[[`,"","key")
  draw_many<-function(shapes,ii,col,border,lwd,lty=1L) {
    if(!length(ii))return()
    xx<-unlist(lapply(shapes[ii],function(s)c(s$x,NA_real_)));yy<-unlist(lapply(shapes[ii],function(s)c(s$y,NA_real_)))
    polypath(head(xx,-1),head(yy,-1),col=col,border=border,lwd=lwd,lty=lty,rule="evenodd")
  }
  panel<-function(r,fig) {
    par(fig=fig,new=TRUE,mar=c(0,0,0,0));plot.new();b<-r$bounds
    plot.window(xlim=b[1:2],ylim=log(tan(pi/4+b[3:4]*pi/360))*180/pi,asp=1,xaxs="i",yaxs="i")
    rect(-400,-150,400,200,col="#edf3f6",border=NA)
    ix<-if(r$key=="US")which(!st%in%extra)else which(st%in%r$states)
    for(bin in 0:5)draw_many(cs,ix[bins[ix]==bin],if(bin==0)"white"else wm_colours()[bin],"#8b9ba5",.20,if(bin==0)2L else 1L)
    si<-if(r$key=="US")which(!sst%in%extra)else which(sst%in%r$states)
    draw_many(ss,si,NA,"#4e6573",.6)
    if(nrow(sites)) {
      q<-sites[sites$longitude>=b[1]&sites$longitude<=b[2]&sites$latitude>=b[3]&sites$latitude<=b[4],]
      points(q$longitude,log(tan(pi/4+q$latitude*pi/360))*180/pi,pch=21,cex=.4,bg="white",col="#163d50")
    }
  }
  panel(regions[[1]],c(.02,.98,.355,.895));left<-c(.02,.255,.405,.605,.715,.805,.9);right<-c(.245,.395,.595,.705,.795,.89,.98)
  for(j in 1:7)panel(regions[[j+1]],c(left[j],right[j],.205,.325))
  par(fig=c(0,1,0,1),new=TRUE,mar=c(0,0,0,0));plot.new();plot.window(xlim=c(0,1),ylim=c(0,1))
  for(j in 1:7)text((left[j]+right[j])/2,.337,regions[[j+1]]$label,cex=.72,font=2,col="#244b5f")
  for(j in 1:6) { x<-.03+(j-1)*.162;rect(x,.161,x+.016,.178,col=if(j<=5)wm_colours()[j]else"white",border="#718591",lty=if(j==6)2 else 1)
    text(x+.022,.169,if(j<=5)wm_labels()[j]else"No observation",adj=0,cex=.65) }
  text(.03,.130,paste("County median of reporting sites |",if(CATEGORY_SCHEME=="cdc_2026")"CDC August 2026 cutoffs"else"Earlier cutoffs used by PMC","| Same cutoffs for every date"),adj=0,cex=.72)
  text(.03,.100,"WVAL is a standardized index, not infection prevalence. County coloring does not imply full population coverage.",adj=0,cex=.69,col="#4d6472")
  text(.03,.073,"Missing stays missing; shared catchments can color multiple counties. Insets have different scales.",adj=0,cex=.69,col="#4d6472")
  text(.03,.046,paste0("CDC atcp-73re; retrospective snapshot | Week ",k," / ",length(weeks)," | Census 2020 boundaries"),adj=0,cex=.69,col="#4d6472")
  segments(.72,.025,.97,.025,col="#d4dfe6",lwd=4);progress<-if(length(weeks)>1)(k-1)/(length(weeks)-1)else 1
  segments(.72,.025,.72+.25*progress,.025,col="#256c8b",lwd=4);points(.72+.25*progress,.025,pch=16,col="#256c8b",cex=.8)
}
wm_fast_shapes <- function(geo) lapply(wm_shapes(geo),function(s) {
  s$x<-head(unlist(lapply(s$rings,function(r)c(r[,1],NA_real_))),-1)
  s$y<-head(unlist(lapply(s$rings,function(r)c(r[,2],NA_real_))),-1);s$rings<-NULL;s
})

run_us_wastewater_positivity_map <- function() {
  missing<-c("curl","jsonlite")[!vapply(c("curl","jsonlite"),requireNamespace,logical(1),quietly=TRUE)]
  if(length(missing))wm_fail("Install packages in a clean R session: ",paste(missing,collapse=", "))
  if(!CATEGORY_SCHEME%in%c("cdc_2026","earlier_pmc")||GIF_WIDTH<1000||GIF_HEIGHT<700||SECONDS_PER_WEEK<.1)wm_fail("Invalid map settings.")
  dir.create(OUTPUT_ROOT,recursive=TRUE,showWarnings=FALSE);cache<-file.path(OUTPUT_ROOT,"cache");dir.create(cache,showWarnings=FALSE)
  run<-tempfile(paste0("run_",format(Sys.time(),"%Y%m%d_%H%M%S",tz="UTC"),"_"),tmpdir=OUTPUT_ROOT)
  dir.create(run);for(n in c("data","sources","frames"))dir.create(file.path(run,n))
  complete<-FALSE;on.exit({capture.output(sessionInfo(),file=file.path(run,"session_info.txt"));if(!complete)writeLines("INCOMPLETE: see R error; HTML/CSV may already be usable.",file.path(run,"RUN_FAILED.txt"))},add=TRUE)
  counties<-jsonlite::fromJSON(wm_asset("counties"),simplifyVector=FALSE);states<-jsonlite::fromJSON(wm_asset("states"),simplifyVector=FALSE)
  areas<-wm_areas(counties)
  w<-wm_source(WVAL_DATASET,"pathogen_target='SARS-CoV-2'",
    "state_territory,counties_served,site,population_served,source,site_wval,site_wval_category,week_end,pathogen_target,date_updated",
    "week_end,site,source",cache,run,LOCAL_WASTEWATER_CSV)
  p<-wm_source(POSITIVITY_DATASET,"1=1","state_name,county_name,fips_code,date,percent_test_results_reported",
    "date,fips_code",cache,run,LOCAL_POSITIVITY_CSV)
  for(src in list(w,p)) {
    jsonlite::write_json(src$manifest,file.path(run,"sources",paste0(src$manifest$dataset,"_manifest.json")),pretty=TRUE,auto_unbox=TRUE,na="null")
    if(!is.null(src$folder))file.copy(file.path(src$folder,"metadata.json"),file.path(run,"sources",paste0(src$manifest$dataset,"_metadata.json")))
  }
  ww<-wm_prepare_wastewater(w$data,areas,run);pos<-wm_prepare_positivity(p$data,areas,run)
  observed_pos<-pos[is.finite(pos$positivity),]
  if(!nrow(observed_pos)||!nrow(ww$county))wm_fail("No mapped observations.")
  first<-min(c(ww$county$week_end,observed_pos$week_end+3L));last<-max(c(ww$county$week_end,observed_pos$week_end+3L))
  weeks<-seq(first,last,by="7 days")
  if(nzchar(START_DATE))weeks<-weeks[weeks>=wm_date(START_DATE)]
  if(nzchar(END_DATE))weeks<-weeks[weeks<=wm_date(END_DATE)]
  if(!length(weeks))wm_fail("No weeks selected.")
  cw<-ww$county[ww$county$week_end%in%weeks,];cp<-pos[(pos$week_end+3L)%in%weeks,]
  wi<-match(cw$week_end,weeks);ci<-match(cw$fips,areas$fips)
  pi<-match(cp$week_end+3L,weeks);pc<-match(cp$fips,areas$fips)
  wrows<-cbind(wi-1L,ci-1L,cw$wval,cw$sites,cw$shared_sites,as.integer(cw$site_membership_changed),as.integer(cw$maximum_site_wval>60))
  good<-is.finite(cp$positivity);prows<-cbind(pi[good]-1L,pc[good]-1L,cp$positivity[good])
  coverage<-data.frame(frame_end=weeks,wastewater_start=weeks-6L,wastewater_end=weeks,
    positivity_start=weeks-9L,positivity_end=weeks-3L,wastewater_counties=tabulate(wi,nbins=length(weeks)),
    positivity_counties=tabulate(pi[good],nbins=length(weeks)),both_counties=integer(length(weeks)))
  for(i in seq_along(weeks))coverage$both_counties[i]<-sum(cw$fips[wi==i]%in%cp$fips[pi==i&is.finite(cp$positivity)])
  wm_csv(coverage,file.path(run,"data","weekly_coverage.csv"));wm_csv(areas,file.path(run,"data","boundary_counties.csv"))
  paired<-merge(cw,transform(pos,frame_end=week_end+3L),by.x=c("fips","week_end"),by.y=c("fips","frame_end"),suffixes=c("_wastewater","_positivity"),all.x=TRUE)
  paired$alignment_note<-"Display only: wastewater Sun-Sat, positivity Thu-Wed ending 3 days earlier"
  wm_csv(paired,file.path(run,"data","display_aligned_counties.csv"))
  sites<-data.frame(SITEID=character(),site_name=character(),latitude=numeric(),longitude=numeric())
  if(nzchar(CLINICAL_SITES_CSV)&&file.exists(CLINICAL_SITES_CSV)) {
    sites<-wm_read(CLINICAL_SITES_CSV);wm_need(sites,c("SITEID","site_name","latitude","longitude"))
    sites<-sites[c("SITEID","site_name","latitude","longitude")];sites$latitude<-wm_num(sites$latitude);sites$longitude<-wm_num(sites$longitude)
    if(any(!is.finite(sites$latitude)|!is.finite(sites$longitude)|abs(sites$latitude)>90|abs(sites$longitude)>180))wm_fail("Invalid clinical site coordinates.")
  }
  dates<-list(wastewater_first=as.character(min(ww$county$week_end)),wastewater_last=as.character(max(ww$county$week_end)),
    positivity_first=as.character(min(observed_pos$week_end)),positivity_last=as.character(max(observed_pos$week_end)),
    wval_updated=paste(unique(ww$raw$date_updated),collapse="; "))
  payload<-list(weeks=I(as.character(weeks)),areas=areas,wastewater=wrows,positivity=prows,sites=sites,
    regions=lapply(wm_regions(),function(r){r$bounds<-I(r$bounds);r$states<-I(r$states);r}),
    coverage=coverage,dates=dates,created=wm_now(),scheme=CATEGORY_SCHEME,delay=SECONDS_PER_WEEK,
    unresolved_county_links=ww$unresolved,large_wval_rows=ww$large_values,gif_expected=WRITE_GIF)
  # Split the small UTF-8 template BEFORE inserting large payloads. This avoids
  # multibyte substring-offset problems in older R versions with long strings.
  template<-wm_asset("template")
  inserts<-list(`__LEAFLET_CSS__`=wm_asset("leaflet_css"),`__LEAFLET_JS__`=wm_asset("leaflet_js"),
    `__PAYLOAD__`=wm_pack(wm_json(payload)),`__COUNTIES__`=wm_pack(wm_asset("counties")),`__STATES__`=wm_pack(wm_asset("states")))
  locations<-vapply(names(inserts),function(t)as.integer(regexpr(t,template,fixed=TRUE)),integer(1))
  if(any(locations<1L))wm_fail("Missing HTML template token.")
  pieces<-list();from<-1L
  for(j in order(locations)) {
    pieces<-c(pieces,list(substr(template,from,locations[j]-1L),inserts[[j]]))
    from<-locations[j]+nchar(names(inserts)[j])
  }
  html<-paste0(c(pieces,list(substring(template,from))),collapse="")
  index<-file.path(run,"index.html");writeLines(enc2utf8(html),index,useBytes=TRUE)
  wm_csv(data.frame(parameter=c("category_scheme","start","end","seconds_per_week","gif_width","gif_height","county_boundary_source"),
    value=c(CATEGORY_SCHEME,as.character(min(weeks)),as.character(max(weeks)),SECONDS_PER_WEEK,GIF_WIDTH,GIF_HEIGHT,
      "US Census 2020: cb_2020_us_county_20m.zip; small territory boundaries 1:500k")),file.path(run,"settings.csv"))
  writeLines(c("US wastewater + positivity map",paste("Created",wm_now()),
    "Open index.html in a modern browser. It is fully offline (requires DecompressionStream support, e.g. current Chrome/Edge/Firefox/Safari).",
    "GIF shows wastewater weeks only; HTML includes the union of positivity and wastewater history.",
    "CDC site-level WVAL: https://data.cdc.gov/d/atcp-73re ; positivity: https://data.cdc.gov/d/jgk8-6dpn",
    "PMC county processing: https://pmc19.com/PMC_COVID_Appendix_June292026.pdf",
    "This map does not copy PMC carry-forward, geographic imputation, prevalence conversion or capping.",
    "County WVAL = unweighted median of reported site WVALs linked to that county in the same week. Never a population estimate.",
    "Shared catchments count once per linked county. Do not sum site populations or treat counties sharing a site as independent.",
    "Mapping uses normalized county names within the plant's reported state. Unresolved cross-state names are exported, not guessed.",
    "Optional reviewed overrides: state_territory,county_label,fips,note in COUNTY_CROSSWALK_CSV.",
    "The 2020 county vintage preserves Connecticut's old county geography used by these archives. County equivalents and inhabited territories are included.",
    "WVAL uses Sunday-Saturday; positivity uses Thursday-Wednesday. Display aligns Saturday with the Wednesday 3 days earlier, preserving actual intervals.",
    "No interpolation, no state substitution, no stale-data carry-forward. Zero is not evidence of no infection.",
    "Site membership and coverage change. Inspect data/site_membership_changes.csv and weekly_coverage.csv.",
    "Large WVAL (>60) rows are retained and flagged for review, not silently capped. The threshold is a display QA marker, not an official exclusion rule.",
    "CDC revised its WVAL methodology in August 2026; historical values are recalculated. Pin source snapshots for reproducible comparisons.",
    "Default color boundaries: 2.6,4.9,7.9,11.6 (CDC Aug 2026). Earlier PMC-default boundaries: 2,3.4,5.3,7.8. Applied to the same current numeric snapshot.",
    "Original paginated API responses remain in cache. A refresh preserves the previous cache under previous_source_snapshot in the new run.",
    "Processed source CSVs, complete metadata and checksums are retained per run. No national incidence curve is fabricated from varying county coverage.",
    "Leaflet 1.9.4 BSD-2-Clause; license retained in embedded source. US Census public geographic data.",
    "R packages are never installed or upgraded automatically."),file.path(run,"README.txt"))
  message("HTML ready: ",normalizePath(index,winslash="/"))
  if(WRITE_GIF) {
    encoder<-wm_encoder();gweeks<-weeks[weeks>=min(ww$county$week_end)&weeks<=max(ww$county$week_end)]
    if(!length(gweeks))wm_fail("The selected dates have no wastewater coverage for a GIF. HTML is ready; change START_DATE/END_DATE or WRITE_GIF.")
    cs<-wm_fast_shapes(counties);ss<-wm_fast_shapes(states);frames<-file.path(run,"frames",paste0("wastewater_",gweeks,".png"))
    for(i in seq_along(gweeks)) {
      if(i==1L||i%%10L==0L||i==length(gweeks))message("Wastewater frame ",i," / ",length(gweeks))
      wm_frame(frames[i],i,gweeks,cw,cs,ss,areas,sites)
    }
    wm_write_gif(frames,file.path(run,"wastewater_levels.gif"),encoder,GIF_WIDTH,GIF_HEIGHT,SECONDS_PER_WEEK)
    if(!KEEP_FRAMES)unlink(frames)
  }
  complete<-TRUE;writeLines(paste("COMPLETE",wm_now()),file.path(run,"RUN_COMPLETE.txt"))
  message("Done: ",normalizePath(run,winslash="/"))
  if(OPEN_HTML)utils::browseURL(index)
  invisible(list(directory=normalizePath(run,winslash="/"),html=normalizePath(index,winslash="/"),coverage=coverage))
}

wm_ring <- function (r) 
{
    m <- matrix(as.numeric(unlist(r)), ncol = 2, byrow = TRUE)
    cbind(m[, 1], log(tan(pi/4 + m[, 2] * pi/360)) * 180/pi)
} 
wm_shapes <- function (geo) 
lapply(geo$features, function(f) {
    polys <- if (f$geometry$type == "Polygon") 
        list(f$geometry$coordinates)
    else if (f$geometry$type == "MultiPolygon") 
        f$geometry$coordinates
    else stop("Unexpected geometry type")
    rings <- unlist(lapply(polys, function(p) lapply(p, wm_ring)), 
        recursive = FALSE)
    list(properties = f$properties, rings = rings)
}) 
wm_draw <- function (shape, fill, border, lwd = 0.5, lty = 1) 
{
    x <- unlist(lapply(shape$rings, function(r) c(r[, 1], NA_real_)))
    y <- unlist(lapply(shape$rings, function(r) c(r[, 2], NA_real_)))
    x <- head(x, -1L)
    y <- head(y, -1L)
    graphics::polypath(x, y, col = fill, border = border, rule = "evenodd", 
        lwd = lwd, lty = lty)
} 
wm_stream_gif <- function (frames, dest, exe, delay) 
{
    temp <- tempfile("animation_", tmpdir = dirname(dest), fileext = ".gif")
    single <- tempfile("gif_frame_", fileext = ".gif")
    con <- file(temp, "wb")
    closed <- FALSE
    on.exit({
        if (!closed) try(close(con), silent = TRUE)
        unlink(c(temp, single))
    }, add = TRUE)
    delay_cs <- max(1L, min(65535L, round(100 * delay)))
    gce <- as.raw(c(33, 249, 4, 4, delay_cs%%256, delay_cs%/%256, 
        0, 0))
    reference_size <- NULL
    for (i in seq_along(frames)) {
        if (is.null(exe)) {
            im <- magick::image_read(frames[i])
            magick::image_write(im, path = single, format = "gif")
            rm(im)
            code <- 0L
        }
        else code <- system2(exe, c(shQuote(normalizePath(frames[i], 
            winslash = "/")), "-background", "white", "-alpha", 
            "remove", "-alpha", "off", "-colors", "256", shQuote(single)))
        if (!identical(code, 0L) || !file.exists(single)) 
            stop("Single-frame GIF conversion failed: ", frames[i])
        b <- readBin(single, "raw", n = file.info(single)$size)
        n <- length(b)
        if (n < 14L || !rawToChar(b[1:6]) %in% c("GIF87a", "GIF89a")) 
            stop("Invalid intermediate GIF")
        byte <- function(k) as.integer(b[k])
        take <- function(a, z) {
            if (a < 1 || z > n || a > z) 
                stop("Truncated intermediate GIF")
            b[a:z]
        }
        packed <- byte(11)
        gsize <- if (bitwAnd(packed, 128L)) 
            3L * 2L^(bitwAnd(packed, 7L) + 1L)
        else 0L
        global <- if (gsize) 
            take(14L, 13L + gsize)
        else raw()
        pos <- 14L + gsize
        images <- 0L
        size <- as.integer(b[7:10])
        if (is.null(reference_size)) {
            reference_size <- size
            header <- take(1L, 13L + gsize)
            header[1:6] <- charToRaw("GIF89a")
            writeBin(header, con)
            writeBin(c(as.raw(c(33, 255, 11)), charToRaw("NETSCAPE2.0"), 
                as.raw(c(3, 1, 0, 0, 0))), con)
        }
        else if (!identical(size, reference_size)) 
            stop("GIF frames have different dimensions")
        skip_blocks <- function(p) {
            repeat {
                if (p > n) 
                  stop("Truncated GIF blocks")
                len <- byte(p)
                p <- p + 1L
                if (len == 0L) 
                  return(p)
                p <- p + len
                if (p > n + 1L) 
                  stop("Truncated GIF block")
            }
        }
        while (pos <= n) {
            tag <- byte(pos)
            if (tag == 59L) 
                break
            if (tag == 33L) {
                pos <- skip_blocks(pos + 2L)
                next
            }
            if (tag != 44L) 
                stop("Unexpected GIF block tag")
            desc <- take(pos, pos + 9L)
            ip <- as.integer(desc[10])
            has_local <- bitwAnd(ip, 128L) > 0
            if (any(as.integer(desc[2:5]) != 0L) || !identical(as.integer(desc[6:9]), 
                reference_size)) 
                stop("Expected a full-size opaque frame")
            pos <- pos + 10L
            if (has_local) {
                len <- 3L * 2L^(bitwAnd(ip, 7L) + 1L)
                palette <- take(pos, pos + len - 1L)
                pos <- pos + len
                palette_bits <- bitwAnd(ip, 7L)
            }
            else {
                if (!length(global)) 
                  stop("Missing GIF palette")
                palette <- global
                palette_bits <- bitwAnd(packed, 7L)
            }
            desc[10] <- as.raw(bitwOr(bitwAnd(ip, 64L), bitwOr(128L, 
                palette_bits)))
            data_start <- pos
            pos <- skip_blocks(pos + 1L)
            writeBin(gce, con)
            writeBin(desc, con)
            writeBin(palette, con)
            writeBin(take(data_start, pos - 1L), con)
            images <- images + 1L
        }
        if (images != 1L) 
            stop("Expected exactly one image in intermediate GIF")
        if (i == 1L || i%%20L == 0L || i == length(frames)) 
            message("[GIF encode ", i, "/", length(frames), "]")
    }
    writeBin(as.raw(59L), con)
    close(con)
    closed <- TRUE
    if (!file.copy(temp, dest, overwrite = TRUE)) 
        stop("Cannot save encoded GIF")
} 
wm_write_gif <- function (frames, dest, encoder, width, height, delay) 
{
    if (encoder$type == "gifski") 
        gifski::gifski(frames, gif_file = dest, width = width, 
            height = height, delay = delay, loop = TRUE)
    else if (encoder$type == "magick") {
        wm_stream_gif(frames, dest, NULL, delay)
    }
    else {
        wm_stream_gif(frames, dest, encoder$exe, delay)
    }
    if (!file.exists(dest) || file.info(dest)$size < 100) 
        stop("GIF file was not produced.")
} 
