list(list(key = "US", label = "Contiguous US + DC", states = character(), 
    bounds = c(-126, -66, 24, 50)), list(key = "AK", label = "Alaska", 
    states = "AK", bounds = c(-190, -129, 50, 72)), list(key = "HI", 
