        18.8, 22.5)), list(key = "PR", label = "Puerto Rico", 
    states = "PR", bounds = c(-67.4, -65.1, 17.8, 18.6)), list(key = "VI", 
    label = "US Virgin Islands", states = "VI", bounds = c(-65.15, 
        -64.45, 17.6, 18.45)), list(key = "GU", label = "Guam", 
    states = "GU", bounds = c(144.55, 145.05, 13.15, 13.75)), 
    list(key = "MP", label = "N. Mariana Islands", states = "MP", 
        bounds = c(144.8, 146.2, 14, 20.8)), list(key = "AS", 
        label = "American Samoa", states = "AS", bounds = c(-171.3, 
            -168, -14.8, -10.8))) 

